static void need(bool b,const char*why){if(!b)throw std::runtime_error(why);}
struct SimClock{inline static thread_local uint64_t tick=1000;static uint64_t ticks(){return tick;}static uint64_t toNS(uint64_t n){return n;}static uint64_t unixNS(){return UINT64_C(1700000000000000000)+tick;}static uint64_t threadNS(){return tick;}static void advance(uint64_t n){tick+=n;}};
static std::array<MVKCPUStageInfo,3> info={{{"work",MVKCPUTimingKind::Work},{"failure",MVKCPUTimingKind::Work},{"async",MVKCPUTimingKind::Async}}};
using Sim=MVKCPUTimingTrace<3,8,SimClock>;using Trace=MVKCPUTimingTrace<3,8>;
struct Totals{uint64_t events=0,self=0,unattributed=0,unattributedSelf=0,details=0,overflow=0,unprepared=0,badNesting=0,reports=0,unpairedReports=0;};
static void consume(Trace&t,Totals&n){auto r=t.snapshot();++n.reports;uint64_t zeroEvents=0,zeroSelf=0;for(size_t d=0;d<8;++d)for(size_t p=0;p<3;++p){auto&m=r->rows[d*3+p];need(std::accumulate(m.inclusiveHistogram.begin(),m.inclusiveHistogram.end(),uint64_t(0))==m.count,"histogram split");n.events+=m.count+m.failures;n.self+=m.selfNS;if(!d){zeroEvents+=m.count+m.failures;zeroSelf+=m.selfNS;}}n.unattributed+=r->detailedUnattributedEvents;n.unattributedSelf+=r->detailedUnattributedSelfNS;if(zeroEvents!=r->detailedUnattributedEvents||zeroSelf!=r->detailedUnattributedSelfNS)++n.unpairedReports;for(auto&s:r->submissions){need(s.context.submission!=0,"zero submission entered table");for(auto&p:s.phases)n.details+=p.count+p.failures;}n.overflow+=r->detailedOverflowEvents;n.unprepared+=r->detailedUnpreparedEvents;n.badNesting+=r->badNesting;}
