 Sim s(info,5000000000ULL,UINT64_MAX);s.setEnabled(true);s.setDetailedEnabled(true);{Sim::Scope outer(s,0);SimClock::advance(10);{Sim::Scope inner(s,1);SimClock::advance(20);}SimClock::advance(30);}s.recordAsync(2,77);s.recordFailure(1,-4);auto exact=s.snapshot();need(exact->detailedUnattributedEvents==4&&exact->detailedUnattributedSelfNS==60,"scope/async/failure total wrong");++checks;need(exact->rows[0].selfNS==40&&exact->rows[1].selfNS==20&&exact->submissions.empty(),"nested self or table changed");++checks;FILE*f=fopen((out+"/deterministic.json").c_str(),"w");need(f,"output failed");s.writeJSON(f,*exact);fclose(f);
 s.setDetailedEnabled(false);{Sim::Scope off(s,0);SimClock::advance(5);}auto off=s.snapshot();need(off->rows[0].count==1&&!off->detailedUnattributedEvents,"detail off changed aggregate/admitted detail");++checks;
 {Sim::Scope crossing(s,0);SimClock::advance(3);s.setDetailedEnabled(true);SimClock::advance(4);auto active=s.snapshot();need(active->inFlight.size()==1&&!active->detailedUnattributedEvents,"inflight counted complete");++checks;}auto closed=s.snapshot();need(closed->rows[0].selfNS==7&&closed->detailedUnattributedEvents==1&&closed->detailedUnattributedSelfNS==7,"arm-during-scope completion lost");++checks;need(!s.snapshot()->detailedUnattributedEvents,"drain doubled events");++checks;
 // Mixed zero/nonzero submissions while reports drain concurrently.
 Trace mixed(info,5000000000ULL,UINT64_MAX);mixed.setEnabled(true);mixed.setDetailedEnabled(true);constexpr unsigned Workers=8,N=6000;std::atomic<unsigned>done{0};std::array<uint64_t,Workers>expectedSelf{};std::vector<std::thread>workers;
 for(unsigned i=0;i<Workers;++i)workers.emplace_back([&,i]{Trace::Context c;c.domain=i<4?0:1;c.queueFamily=i<4?UINT32_MAX:0;c.queueIndex=i%2;c.submission=i<4?0:100+i;Trace::ContextGuard context(c);for(unsigned j=0;j<N;++j){Trace::Scope scope(mixed,0);std::atomic_signal_fence(std::memory_order_seq_cst);expectedSelf[i]+=scope.finish();if(j%8==0)mixed.recordAsync(2,11);if(j%16==0)mixed.recordFailure(1,-7);}++done;});
 Totals totals;while(done.load()!=Workers){consume(mixed,totals);std::this_thread::sleep_for(std::chrono::microseconds(100));}for(auto&w:workers)w.join();consume(mixed,totals);uint64_t expectedEach=N+(N+7)/8+(N+15)/16;need(totals.events==Workers*expectedEach&&totals.unattributed==4*expectedEach&&totals.details==4*expectedEach,"concurrent drain count lost or doubled");++checks;need(totals.unattributedSelf==std::accumulate(expectedSelf.begin(),expectedSelf.begin()+4,uint64_t(0)),"concurrent drain self sum lost");++checks;need(!totals.overflow&&!totals.unprepared&&!totals.badNesting,"concurrent attributed coverage lost");++checks;
