 for(unsigned i=0;i<Workers;++i)workers.emplace_back([&,i]{for(unsigned p=0;p<Phases;++p){while(phase.load(std::memory_order_acquire)<int(p))std::this_thread::yield();for(unsigned j=0;j<PerPhase;++j){Trace::Scope scope(arms,0);auto ns=scope.finish();if(p%2)admittedSelf[i]+=ns;}++phaseDone[p];}});
 Totals armTotals;for(unsigned p=0;p<Phases;++p){arms.setDetailedEnabled(p%2);phase.store(p,std::memory_order_release);while(phaseDone[p].load()!=Workers){consume(arms,armTotals);std::this_thread::sleep_for(std::chrono::microseconds(100));}consume(arms,armTotals);}for(auto&w:workers)w.join();consume(arms,armTotals);need(armTotals.events==Workers*Phases*PerPhase&&armTotals.unattributed==Workers*2*PerPhase,"arm epoch event totals lost");++checks;need(armTotals.unattributedSelf==std::accumulate(admittedSelf.begin(),admittedSelf.end(),uint64_t(0)),"arm epoch self totals lost");++checks;
 // Full production phase-count shape, eight zero-submission producers.
 std::array<MVKCPUStageInfo,75> fullInfo;for(auto&i:fullInfo)i={"empty-scope",MVKCPUTimingKind::Work};using Bench=MVKCPUTimingTrace<75,8>;std::array<double,3>wallMS{},threadCPUMS{};std::array<uint64_t,3>benchSelf{};
 constexpr unsigned Loops=25000,Warm=1000;for(unsigned run=0;run<3;++run){Bench b(fullInfo,5000000000ULL,UINT64_MAX);b.setEnabled(true);b.setDetailedEnabled(true);std::atomic<unsigned>ready{0};std::atomic<bool>start{false};std::array<uint64_t,Workers>cpu{},self{};workers.clear();for(unsigned i=0;i<Workers;++i)workers.emplace_back([&,i]{for(unsigned j=0;j<Warm;++j){Bench::Scope warm(b,0);}++ready;while(!start.load(std::memory_order_acquire))std::this_thread::yield();auto c=MVKCPUDefaultClock::threadNS();for(unsigned j=0;j<Loops;++j){Bench::Scope scope(b,0);self[i]+=scope.finish();}cpu[i]=MVKCPUDefaultClock::threadNS()-c;});while(ready.load()!=Workers)std::this_thread::yield();auto warm=b.snapshot();need(warm->detailedUnattributedEvents==Workers*Warm,"benchmark warmup not exact");auto t=std::chrono::steady_clock::now();start.store(true,std::memory_order_release);for(auto&w:workers)w.join();wallMS[run]=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();threadCPUMS[run]=std::accumulate(cpu.begin(),cpu.end(),uint64_t(0))/1e6;auto r=b.snapshot();benchSelf[run]=std::accumulate(self.begin(),self.end(),uint64_t(0));need(r->rows[0].count==Workers*Loops&&r->detailedUnattributedEvents==Workers*Loops&&r->detailedUnattributedSelfNS==benchSelf[run]&&r->submissions.empty(),"benchmark count/self totals wrong");++checks;}
 auto median=[](auto a){std::sort(a.begin(),a.end());return a[1];};std::ofstream report(out+"/result.json");report<<"{\"passed\":true,\"baseline\":"<<(CPU_UNATTRIBUTED_BASELINE?"true":"false")<<",\"checks\":"<<checks<<",\"GPUCommands\":0,\"gameOperations\":0,\"concurrentEvents\":"<<totals.events<<",\"unattributedEvents\":"<<totals.unattributed<<",\"attributedEvents\":"<<totals.details<<",\"drainReports\":"<<totals.reports<<",\"aggregateUnattributedUnpairedReports\":"<<totals.unpairedReports<<",\"armAggregateEvents\":"<<armTotals.events<<",\"armAdmittedUnattributedEvents\":"<<armTotals.unattributed<<",\"allCountAndSelfTotalsExact\":true,\"benchmarkThreads\":8,\"benchmarkEventsPerRun\":"<<Workers*Loops<<",\"wallMSMedian\":"<<median(wallMS)<<",\"threadCPUSumMSMedian\":"<<median(threadCPUMS)<<",\"wallMS\":["<<wallMS[0]<<","<<wallMS[1]<<","<<wallMS[2]<<"],\"threadCPUSumMS\":["<<threadCPUMS[0]<<","<<threadCPUMS[1]<<","<<threadCPUMS[2]<<"],\"notGameFPS\":true}\n";std::cout<<"PASS checks="<<checks<<" wallMedianMS="<<median(wallMS)<<"\n";return 0;
